function fm_user():string{
    global $loginname;
    $u=trim((string)($loginname??$_SESSION['loginname']??$_SESSION['username']??''));
    if($u===''||strcasecmp($u,'System')===0)throw new RuntimeException('Logged-in user could not be identified. Please refresh and try again.');
    return $u;
}
function fm_header_aliases():array{return [
    'invoiceid'=>['invoice_id','invoiceid'],'companyid'=>['companyid','company_id'],'subcompanyid'=>['subcompanyid','subcompany_id'],
    'projectid'=>['projectid','project_id'],'clientid'=>['clientid','client_id','customerid','customer_id'],'clientname'=>['clientname','client_name','customername','customer_name'],
    'invoicetype'=>['invoice_type','invoicetype','type'],'invoiceno'=>['invoice_no','invoiceno','invoice_number','billno','bill_no'],'invoicedate'=>['invoice_date','invoicedate','date'],
    'financialyear'=>['financial_year','financialyear','finyr'],'source'=>['source','source_table','datatype'],'refno'=>['refno'],'description'=>['description'],
    'original'=>['original_freight','original_amount','totalrowsamount','subtotal','amount'],'billing'=>['billing_freight','billing_amount','freight_amount','item_amount'],
    'discountpct'=>['discount_percent','discountpercent'],'discount'=>['discount_amount','totalrowsdiscount','discount'],'adjustment'=>['adjustment','adjustment_amount','otherdiscount'],
    'taxable'=>['taxableamount','taxable_amount'],'gst'=>['invoicegstamount','gst_amount','totalgstamount'],'total'=>['totalpayableamount','invoice_amount','total_amount','payable_amount'],
    'cgstpct'=>['cgst_percent','cgstpercent'],'sgstpct'=>['sgst_percent','sgstpercent'],'igstpct'=>['igst_percent','igstpercent'],
    'cgstamt'=>['cgst_amount','cgstamount'],'sgstamt'=>['sgst_amount','sgstamount'],'igstamt'=>['igst_amount','igstamount'],
    'reason'=>['adjustment_reason','discount_reason','reason'],'remarks'=>['remarks','remark'],'createdby'=>['created_by','createdby','loginid','loginname'],
    'createdat'=>['created_at','createdon'],'invoicepath'=>['invoicepath','invoice_path','invoicefilepath','invoice_file_path','filepath']
];}
function fm_pending(mysqli $db,int $p):array{
    $sql="SELECT f.clientid,MAX(f.clientname) clientname,f.trip_id,MAX(t.dispatch_at) trip_date,MAX(t.vehicle_no) vehicle_no,MAX(t.driver_name) driver_name,MAX(t.source_locationname) source_locationname,MAX(t.destination_locationname) destination_locationname,MAX(t.total_distance_km) distance_km,SUM(COALESCE(f.payable_freight_amount,0)) original_freight FROM krf_transport_trip_client_freight f INNER JOIN krf_transport_trip t ON t.projectid=f.projectid AND t.trip_id=f.trip_id AND t.transport_type='Client' WHERE f.projectid=? AND COALESCE(f.freight_recoverable,0)=1 AND COALESCE(f.freight_invoice_id,0)=0 AND t.status IN ('In-Transit','In Transit','Delivered','Received','Completed') GROUP BY f.clientid,f.trip_id ORDER BY MAX(f.clientname),MAX(t.dispatch_at),f.trip_id";
    $st=$db->prepare($sql);if(!$st)throw new RuntimeException('Pending freight query failed: '.$db->error);$st->bind_param('i',$p);$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();return $rows;
}
function fm_generated(mysqli $db,int $p):array{
    $sql="SELECT f.freight_invoice_id invoice_id,MAX(f.freight_invoice_no) invoice_no,MAX(f.freight_invoice_date) invoice_date,MAX(f.freight_invoice_path) invoice_path,f.clientid,MAX(f.clientname) clientname,GROUP_CONCAT(DISTINCT f.trip_id ORDER BY f.trip_id SEPARATOR ', ') trip_ids,COUNT(DISTINCT f.trip_id) trip_count,GROUP_CONCAT(DISTINCT NULLIF(TRIM(t.vehicle_no),'') ORDER BY t.vehicle_no SEPARATOR ', ') vehicle_no,GROUP_CONCAT(DISTINCT NULLIF(TRIM(t.driver_name),'') ORDER BY t.driver_name SEPARATOR ', ') driver_name,MAX(f.billing_invoice_amount) invoice_amount FROM krf_transport_trip_client_freight f LEFT JOIN krf_transport_trip t ON t.projectid=f.projectid AND t.trip_id=f.trip_id AND t.transport_type='Client' WHERE f.projectid=? AND COALESCE(f.freight_invoice_id,0)>0 GROUP BY f.freight_invoice_id,f.clientid ORDER BY MAX(f.freight_invoice_date) DESC,f.freight_invoice_id DESC";
    $st=$db->prepare($sql);if(!$st)throw new RuntimeException('Generated invoice query failed: '.$db->error);$st->bind_param('i',$p);$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();return $rows;
}
function fm_pdf(mysqli $mconn,array $hcols,int $invoiceId,string $invoiceNo,string $date,string $fy,array $client,array $lines,array $totals,string $reason,string $remarks,string $by):string{
    $pathCol=cfi_pick($hcols,['invoicepath','invoice_path','invoicefilepath','invoice_file_path','filepath']);$idCol=cfi_pick($hcols,['invoice_id','invoiceid']);
    if(!$pathCol||!$idCol)throw new RuntimeException('tbl_invoices requires invoice ID and invoice path columns.');
    require_once dirname(__DIR__).'/config_document_storage.php';$tcpdf=TRANSPORT_DOCUMENT_APP_ROOT.'/pdfroutines/tcpdf/tcpdf.php';if(!is_file($tcpdf))throw new RuntimeException('TCPDF library was not found.');require_once $tcpdf;require_once dirname(__DIR__).'/TransportStoredPdfRenderer.php';
    $dirRel='attachementfile/client_freight_invoices/'.date('Y',strtotime($date)).'/'.date('m',strtotime($date));$dir=rtrim(TRANSPORT_DOCUMENT_APP_ROOT,'/\\').DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$dirRel);if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir))throw new RuntimeException('Unable to create invoice PDF folder.');
    $name=(preg_replace('/[^A-Za-z0-9_-]+/','_',$invoiceNo)?:('FREIGHT_'.$invoiceId)).'.pdf';$rel=$dirRel.'/'.$name;$physical=$dir.DIRECTORY_SEPARATOR.$name;
    $pdf=new TCPDF(PDF_PAGE_ORIENTATION,PDF_UNIT,PDF_PAGE_FORMAT,true,'UTF-8',false);$pdf->SetCreator('Karjee Farms');$pdf->SetAuthor('Karjee Farms');$pdf->SetTitle($invoiceNo);$pdf->SetMargins(12,10,12);$pdf->SetAutoPageBreak(true,13);$pdf->setPrintHeader(false);$pdf->setPrintFooter(false);$pdf->AddPage();
    $renderer=new TransportStoredPdfRenderer($pdf,transport_document_brand());
    $renderer->writeCommonHeader('CLIENT FREIGHT INVOICE',$invoiceNo);
    if(function_exists('transport_pdf_display_data')){$client=transport_pdf_display_data($client);$lines=transport_pdf_display_data($lines);$reason=transport_pdf_display_text($reason);$remarks=transport_pdf_display_text($remarks);}
    $e=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
    $pdf->SetFont('helvetica','',9);
    $identity='<table border="1" cellpadding="5" cellspacing="0" width="100%"><tr style="background-color:#eeeeee;font-weight:bold;"><td width="34%">Invoice Date</td><td width="33%">Financial Year</td><td width="33%">Client Code</td></tr><tr><td width="34%">'.$e(date('d-m-Y',strtotime($date))).'</td><td width="33%">'.$e($fy).'</td><td width="33%">'.$e($client['clientid']??'').'</td></tr></table><br>';
    $address=trim((string)($client['billing_address']??''));
    $identity.='<table border="1" cellpadding="5" cellspacing="0" width="100%"><tr style="background-color:#eeeeee;font-weight:bold;"><td>Bill To</td></tr><tr><td><b>'.$e($client['clientname']??'').'</b>'.($address!==''?'<br>'.nl2br($e($address)):'').'</td></tr></table><br>';
    $pdf->writeHTML($identity,true,false,true,false,'');
    $pdf->SetFont('helvetica','B',10.5);$pdf->Cell(0,6,'Trip-wise Freight Details',0,1,'L');
    $html='<table border="1" cellpadding="4" cellspacing="0" width="100%"><thead><tr style="font-weight:bold;background-color:#f2f2f2;">'
        .'<th width="16%">Trip No.</th><th width="11%">Date</th><th width="29%">Route / Vehicle</th><th width="11%" align="right">Original</th><th width="11%" align="right">Discount</th><th width="11%" align="right">Adjustment</th><th width="11%" align="right">Taxable</th></tr></thead><tbody>';
    foreach($lines as $x){$vehicle=trim((string)($x['vehicle_no']??''));$html.='<tr><td width="16%">'.$e($x['trip_id']??'').'</td><td width="11%">'.$e(!empty($x['trip_date'])?date('d-m-Y',strtotime((string)$x['trip_date'])):'-').'</td><td width="29%">'.$e(trim((string)($x['source_locationname']??'').' - '.(string)($x['destination_locationname']??''))).($vehicle!==''?'<br><b>Vehicle:</b> '.$e($vehicle):'').'</td><td width="11%" align="right">'.number_format((float)$x['original'],2).'</td><td width="11%" align="right">'.number_format((float)$x['discount'],2).'</td><td width="11%" align="right">'.number_format((float)$x['adjustment'],2).'</td><td width="11%" align="right">'.number_format((float)$x['taxable'],2).'</td></tr>';}
    $html.='</tbody></table><br>';
    $pdf->SetFont('helvetica','',8.5);$pdf->writeHTML($html,true,false,true,false,'');
    $summary='<table border="1" cellpadding="5" cellspacing="0" width="50%" align="right"><tr><td width="62%">Taxable Freight</td><td width="38%" align="right">'.number_format((float)$totals['taxable'],2).'</td></tr><tr><td>CGST</td><td align="right">'.number_format((float)$totals['cgst'],2).'</td></tr><tr><td>SGST</td><td align="right">'.number_format((float)$totals['sgst'],2).'</td></tr><tr><td>IGST</td><td align="right">'.number_format((float)$totals['igst'],2).'</td></tr><tr style="font-weight:bold;background-color:#eeeeee;"><td>Invoice Amount</td><td align="right">'.number_format((float)$totals['invoice'],2).'</td></tr></table>';
    $pdf->SetFont('helvetica','',9);$pdf->writeHTML($summary,true,false,true,false,'');
    if($reason!==''||$remarks!==''){$pdf->Ln(3);$pdf->SetFont('helvetica','B',10);$pdf->Cell(0,6,'Billing Notes',0,1,'L');$notes='';if($reason!=='')$notes.='<b>Discount / Adjustment Reason:</b> '.$e($reason);if($remarks!=='')$notes.=($notes!==''?'<br>':'').'<b>Remarks:</b> '.$e($remarks);$pdf->SetFont('helvetica','',8.5);$pdf->writeHTML('<table border="1" cellpadding="5"><tr><td>'.$notes.'</td></tr></table>',true,false,true,false,'');}
    $pdf->Ln(13);$pdf->SetFont('helvetica','',9);$pdf->writeHTML('<table cellpadding="3" width="100%"><tr><td width="33%" align="center">Prepared By<br><b>'.$e($by).'</b></td><td width="34%" align="center">Accounts</td><td width="33%" align="center">Authorized Signatory</td></tr><tr><td style="border-top:1px solid #000"></td><td style="border-top:1px solid #000"></td><td style="border-top:1px solid #000"></td></tr></table>',true,false,true,false,'');
    $pdf->SetFont('helvetica','',7.5);$pdf->SetTextColor(90,90,90);$pdf->Cell(0,4,'System-generated Client Freight Invoice. Original Transport Client Freight remains unchanged.',0,1,'L');$pdf->SetTextColor(0,0,0);
    $pdf->Output($physical,'F');if(!is_file($physical)||filesize($physical)<=0)throw new RuntimeException('Invoice PDF could not be created.');
    $st=$mconn->prepare("UPDATE tbl_invoices SET `$pathCol`=? WHERE `$idCol`=?");if(!$st){@unlink($physical);throw new RuntimeException('Invoice path update failed: '.$mconn->error);}$st->bind_param('si',$rel,$invoiceId);$st->execute();$st->close();return $rel;
}

header('Content-Type: application/json; charset=utf-8');
try{
    if(!isset($krfconn)||!($krfconn instanceof mysqli))throw new RuntimeException('$krfconn is unavailable.');if(!isset($mconn)||!($mconn instanceof mysqli))throw new RuntimeException('$mconn is unavailable.');
    $krfconn->set_charset('utf8mb4');$mconn->set_charset('utf8mb4');$action=trim((string)($_POST['action']??''));$p=(int)($_POST['projectid']??0);if($p<=0)throw new InvalidArgumentException('Valid Project ID is required.');
    if($action==='list'){cfi_json(true,'Freight invoice data loaded.',['pending'=>fm_pending($krfconn,$p),'generated'=>fm_generated($krfconn,$p)]);}
    if($action!=='save')throw new InvalidArgumentException('Invalid action.');
    $by=fm_user();$clientId=trim((string)($_POST['clientid']??''));$rows=json_decode((string)($_POST['rows']??'[]'),true);if($clientId===''||!is_array($rows)||!$rows)throw new InvalidArgumentException('Select at least one freight trip for one client.');
    $date=trim((string)($_POST['invoice_date']??''));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new InvalidArgumentException('Valid invoice date is required.');$cfg=cfi_cfg();$fy=cfi_finyr($date,(int)($cfg['financial_year_start_month']??4));$company=(int)($_POST['companyid']??0);$sub=(int)($_POST['subcompanyid']??0);$reason=trim((string)($_POST['reason']??''));$remarks=trim((string)($_POST['remarks']??''));
    $cgstPct=max(0,min(100,(float)($_POST['cgst_percent']??0)));$sgstPct=max(0,min(100,(float)($_POST['sgst_percent']??0)));$igstPct=max(0,min(100,(float)($_POST['igst_percent']??0)));
    $lines=[];$clientName='';$address='';$originalTotal=0;$discountTotal=0;$adjustmentTotal=0;$taxableTotal=0;$tripIds=[];
    foreach($rows as $r){$tripId=trim((string)($r['trip_id']??''));if($tripId===''||isset($tripIds[$tripId]))continue;$f=cfi_one_client_freight($krfconn,$p,$tripId,$clientId);$trip=cfi_trip($krfconn,$p,$tripId);
        $eligibleStatuses=['In-Transit','In Transit','Delivered','Received','Completed'];
        if(strcasecmp((string)($trip['transport_type']??''),'Client')!==0||!in_array((string)($trip['status']??''),$eligibleStatuses,true))throw new RuntimeException('Trip '.$tripId.' is not eligible for client freight invoicing.');
        $check=$krfconn->prepare("SELECT MAX(COALESCE(freight_invoice_id,0)) iid FROM krf_transport_trip_client_freight WHERE projectid=? AND trip_id=? AND clientid=? AND COALESCE(freight_recoverable,0)=1");if(!$check)throw new RuntimeException('Invoice duplicate check failed: '.$krfconn->error);$check->bind_param('iss',$p,$tripId,$clientId);$check->execute();$iid=(int)($check->get_result()->fetch_assoc()['iid']??0);$check->close();if($iid>0)throw new RuntimeException('Trip '.$tripId.' is already invoiced.');
        $original=cfi_money($f['original_freight']);$discPct=max(0,min(100,(float)($r['discount_percent']??0)));$disc=max(0,min($original,cfi_money($r['discount_amount']??0)));if($disc==0.0&&$discPct>0)$disc=cfi_money($original*$discPct/100);$adj=cfi_money($r['adjustment']??0);$taxable=max(0,cfi_money($original-$disc+$adj));
        $lines[]=['trip_id'=>$tripId,'trip_date'=>cfi_trip_date($trip),'source_locationname'=>(string)($trip['source_locationname']??''),'destination_locationname'=>(string)($trip['destination_locationname']??''),'vehicle_no'=>(string)($trip['vehicle_no']??''),'distance'=>cfi_trip_distance($trip),'original'=>$original,'discount'=>$disc,'discount_percent'=>$original>0?round($disc/$original*100,2):0,'adjustment'=>$adj,'taxable'=>$taxable];$tripIds[$tripId]=true;$clientName=(string)$f['clientname'];$address=(string)$f['billing_address'];$originalTotal+=$original;$discountTotal+=$disc;$adjustmentTotal+=$adj;$taxableTotal+=$taxable;
    }
    if(!$lines)throw new InvalidArgumentException('No eligible trip was selected.');if(($discountTotal>0||abs($adjustmentTotal)>0.00001)&&$reason==='')throw new InvalidArgumentException('Discount / Adjustment Reason is required.');
    $cgst=cfi_money($taxableTotal*$cgstPct/100);$sgst=cfi_money($taxableTotal*$sgstPct/100);$igst=cfi_money($taxableTotal*$igstPct/100);$gst=cfi_money($cgst+$sgst+$igst);$invoiceAmount=cfi_money($taxableTotal+$gst);$refs=implode(',',array_keys($tripIds));$invoiceType=(string)($cfg['invoice_type']??'Freight Invoice');
    foreach($lines as &$x){$x['cgst_amount']=cfi_money($x['taxable']*$cgstPct/100);$x['sgst_amount']=cfi_money($x['taxable']*$sgstPct/100);$x['igst_amount']=cfi_money($x['taxable']*$igstPct/100);$x['gst_amount']=cfi_money($x['cgst_amount']+$x['sgst_amount']+$x['igst_amount']);$x['invoice_amount']=cfi_money($x['taxable']+$x['gst_amount']);}unset($x);
    $hcols=cfi_colmeta($mconn,'tbl_invoices');$mconn->begin_transaction();try{$invoiceId=cfi_next_invoice_id($mconn,$fy,$hcols);$invoiceNo=cfi_invoice_no($invoiceId,$fy,$cfg);$vals=['invoiceid'=>$invoiceId,'companyid'=>$company,'subcompanyid'=>$sub,'projectid'=>$p,'clientid'=>$clientId,'clientname'=>$clientName,'invoicetype'=>$invoiceType,'invoiceno'=>$invoiceNo,'invoicedate'=>$date,'financialyear'=>$fy,'source'=>'Transport Client Freight','refno'=>$refs,'description'=>'Consolidated Freight Invoice | Trips: '.$refs,'original'=>$originalTotal,'billing'=>$originalTotal,'discountpct'=>$originalTotal>0?round($discountTotal/$originalTotal*100,2):0,'discount'=>$discountTotal,'adjustment'=>$adjustmentTotal,'taxable'=>$taxableTotal,'gst'=>$gst,'total'=>$invoiceAmount,'cgstpct'=>$cgstPct,'sgstpct'=>$sgstPct,'igstpct'=>$igstPct,'cgstamt'=>$cgst,'sgstamt'=>$sgst,'igstamt'=>$igst,'reason'=>$reason,'remarks'=>$remarks,'createdby'=>$by,'createdat'=>date('Y-m-d H:i:s'),'invoicepath'=>''];cfi_insert_adaptive($mconn,'tbl_invoices',$vals,fm_header_aliases());
        foreach($lines as $x)cfi_ensure_invoice_breakdown($mconn,['invoice_id'=>$invoiceId,'companyid'=>$company,'subcompanyid'=>$sub,'projectid'=>$p,'clientid'=>$clientId,'clientname'=>$clientName,'invoice_type'=>$invoiceType,'invoice_no'=>$invoiceNo,'invoice_date'=>$date,'financial_year'=>$fy,'trip_id'=>$x['trip_id'],'description'=>'Freight for Trip '.$x['trip_id'],'original_freight'=>$x['original'],'billing_freight'=>$x['original'],'trip_distance_km'=>$x['distance'],'discount_percent'=>$x['discount_percent'],'discount_amount'=>$x['discount'],'adjustment_amount'=>$x['adjustment'],'adjustment_reason'=>$reason,'taxable_amount'=>$x['taxable'],'gst_amount'=>$x['gst_amount'],'invoice_amount'=>$x['invoice_amount'],'cgst_percent'=>$cgstPct,'sgst_percent'=>$sgstPct,'igst_percent'=>$igstPct,'cgst_amount'=>$x['cgst_amount'],'sgst_amount'=>$x['sgst_amount'],'igst_amount'=>$x['igst_amount'],'remarks'=>$remarks,'created_by'=>$by]);
        $path=fm_pdf($mconn,$hcols,$invoiceId,$invoiceNo,$date,$fy,['clientid'=>$clientId,'clientname'=>$clientName,'billing_address'=>$address],$lines,['taxable'=>$taxableTotal,'cgst'=>$cgst,'sgst'=>$sgst,'igst'=>$igst,'invoice'=>$invoiceAmount],$reason,$remarks,$by);$mconn->commit();
    }catch(Throwable $e){@$mconn->rollback();throw $e;}
    foreach($lines as $x)cfi_sync_local_invoice($krfconn,$p,$x['trip_id'],$clientId,['invoice_id'=>$invoiceId,'invoice_no'=>$invoiceNo,'invoice_date'=>$date,'financial_year'=>$fy,'invoice_path'=>$path,'discount_percent'=>$x['discount_percent'],'discount_amount'=>$x['discount'],'adjustment_amount'=>$x['adjustment'],'adjustment_reason'=>$reason,'taxable_amount'=>$x['taxable'],'cgst_amount'=>$x['cgst_amount'],'sgst_amount'=>$x['sgst_amount'],'igst_amount'=>$x['igst_amount'],'invoice_amount'=>$invoiceAmount,'generated_at'=>date('Y-m-d H:i:s'),'generated_by'=>$by]);
    $base='prints/invoice.php?invoice_id='.rawurlencode((string)$invoiceId);cfi_json(true,'Consolidated Freight Invoice created successfully.',['invoice_id'=>$invoiceId,'invoice_no'=>$invoiceNo,'invoice_amount'=>$invoiceAmount,'print_url'=>$base.'&mode=inline','download_url'=>$base.'&mode=download']);
}catch(InvalidArgumentException $e){cfi_json(false,$e->getMessage(),[],422);}catch(Throwable $e){cfi_json(false,$e->getMessage(),[],500);}
